    graph,
    shape: shapeOf(graph),
    size: isEmpty(size) ? { columns: 0, rows: 0 } : size,
    world,
    layout: isEmpty(size) ? { pos: {}, temperature: 0 } : fitted(graph, world),
    camera: isEmpty(size) ? { x: 0, y: 0 } : centred(world, size, 1),
    zoom: 1,
    isRunning: !isEmpty(size),
    active: null,
    isCameraSet: false,
    pinned: [],
    drag: null,
    pan: null,
    selected: null,
    hovered: null,
    box,
  }
