        active: null,
        isRunning: !isEmpty(state.size),
        pinned: state.pinned.filter(id => graph.nodes.some(node => node.id === id)),
        selected: graph.nodes.some(node => node.id === state!.selected) ? state.selected : null,
        hovered: null,
      }
      surface.setState(next)
      state = next
    }
